import os
import requests


def ingest_correlated_logs(
    correlation_id: str,
    service_name: str,
    log_events: list[dict],
    api_key: str | None = None,
    app_key: str | None = None,
    site: str | None = None,
) -> requests.Response:
    dd_api_key = api_key or os.environ.get("DD_API_KEY")
    if not dd_api_key:
        raise ValueError("Datadog API key must be provided or set via DD_API_KEY.")

    dd_site = site or os.environ.get("DD_SITE", "datadoghq.com")
    dd_app_key = app_key or os.environ.get("DD_APP_KEY")

    url = f"https://api.{dd_site}/api/v2/logs"
    headers = {
        "Content-Type": "application/json",
        "DD-API-KEY": dd_api_key,
    }
    if dd_app_key:
        headers["DD-APPLICATION-KEY"] = dd_app_key

    payload = {
        "data": [
            {
                "type": "log",
                "attributes": {
                    "message": event.get("message", ""),
                    "status": event.get("status", "info"),
                    "service": service_name,
                    "ddsource": "python-app",
                    "tags": [f"correlation_id:{correlation_id}"],
                },
            }
            for event in log_events
        ]
    }

    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status()
    return response
